CREATE TABLE delivery (id UUID PRIMARY KEY,order_id UUID NOT NULL UNIQUE,customer_id UUID NOT NULL,delivery_agent_id UUID,recipient_name VARCHAR(120) NOT NULL,address_line_1 VARCHAR(200) NOT NULL,address_line_2 VARCHAR(200),city VARCHAR(120) NOT NULL,state_or_region VARCHAR(120) NOT NULL,postal_code VARCHAR(32) NOT NULL,country_code VARCHAR(2) NOT NULL,delivery_instructions VARCHAR(300),status VARCHAR(32) NOT NULL,failure_code VARCHAR(80),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,assigned_at TIMESTAMPTZ,picked_up_at TIMESTAMPTZ,out_for_delivery_at TIMESTAMPTZ,delivered_at TIMESTAMPTZ,failed_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_delivery_country CHECK(country_code ~ '^[A-Z]{2}$'),CONSTRAINT ck_delivery_status CHECK(status IN('PENDING_ASSIGNMENT','ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','FAILED','CANCEL_REQUESTED','CANCELLED')));
CREATE INDEX idx_delivery_customer_created ON delivery(customer_id,created_at DESC);CREATE INDEX idx_delivery_agent_status ON delivery(delivery_agent_id,status);CREATE INDEX idx_delivery_pending ON delivery(created_at,id) WHERE status='PENDING_ASSIGNMENT';
CREATE TABLE delivery_agent_profile(id UUID PRIMARY KEY,user_id UUID NOT NULL UNIQUE,availability VARCHAR(16) NOT NULL,last_assigned_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_agent_availability CHECK(availability IN('OFFLINE','AVAILABLE','BUSY')));
CREATE INDEX idx_agent_assignment ON delivery_agent_profile(last_assigned_at NULLS FIRST,id) WHERE availability='AVAILABLE';
CREATE TABLE delivery_status_history(id UUID PRIMARY KEY,delivery_id UUID NOT NULL REFERENCES delivery(id),previous_status VARCHAR(32),new_status VARCHAR(32) NOT NULL,actor_user_id UUID,source_event_id UUID,correlation_id VARCHAR(128),changed_at TIMESTAMPTZ NOT NULL);CREATE INDEX idx_delivery_history ON delivery_status_history(delivery_id,changed_at,id);
CREATE TABLE outbox_event(id UUID PRIMARY KEY,aggregate_type VARCHAR(64) NOT NULL,aggregate_id UUID NOT NULL,event_type VARCHAR(80) NOT NULL,event_version INTEGER NOT NULL,topic VARCHAR(255) NOT NULL,message_key VARCHAR(128) NOT NULL,payload JSONB NOT NULL,correlation_id VARCHAR(128),causation_id UUID,status VARCHAR(16) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ,last_error_code VARCHAR(200),locked_at TIMESTAMPTZ,locked_by VARCHAR(128),CONSTRAINT ck_delivery_outbox_status CHECK(status IN('NEW','IN_PROGRESS','PUBLISHED','FAILED')));CREATE INDEX idx_delivery_outbox_due ON outbox_event(status,available_at);
CREATE TABLE processed_event(event_id UUID NOT NULL,event_type VARCHAR(80) NOT NULL,aggregate_id UUID NOT NULL,consumer_name VARCHAR(120) NOT NULL,processed_at TIMESTAMPTZ NOT NULL,correlation_id VARCHAR(128),PRIMARY KEY(event_id,consumer_name));
